      position:sticky;
      top:0;
      z-index:30;
      display:flex;
      justify-content:space-between;
      align-items:center;
      gap:24px;
      padding:16px max(20px,calc((100% - 1180px)/2));
      background:rgba(244,241,234,.94);
      border-bottom:1px solid var(--line);
      backdrop-filter:blur(16px);
    }

    .brand{
      display:flex;
      align-items:center;
      gap:12px;
      text-decoration:none;
      font-weight:900;
      font-size:20px;
      letter-spacing:.04em;
    }

    .brand-mark{
      display:grid;
      place-items:center;
      width:42px;
      height:42px;
      border-radius:14px;
      color:#fff;
      background:var(--accent);
      font-weight:900;
    }

    .nav{
      display:flex;
      flex-wrap:wrap;
      gap:8px;
    }

    .nav a{
      padding:8px 11px;
      text-decoration:none;
      border-radius:999px;
      color:var(--muted);
      font-size:16px;
      font-weight:700;
    }

    .nav a:hover{background:var(--surface);color:var(--ink)}

    main{overflow:hidden}

    .hero{
      padding:86px 0 54px;
    }

    .eyebrow{
      display:inline-flex;
      align-items:center;
      gap:8px;
      margin:0 0 18px;
      padding:7px 12px;
      border-radius:999px;
      background:var(--accent-2);
      color:var(--accent);
      font-size:16px;
      font-weight:900;
      letter-spacing:.04em;
    }

    h1,h2,h3,p{margin-top:0}
    h1{
      max-width:900px;
      margin-bottom:24px;
      font-size:clamp(44px,7vw,82px);
      line-height:1.02;
      letter-spacing:-.055em;
    }

    h2{
      margin-bottom:14px;
      font-size:clamp(34px,4vw,50px);
      line-height:1.12;
      letter-spacing:-.035em;
    }

    h3{
      margin-bottom:10px;
      font-size:24px;
      line-height:1.3;
    }

    .lead{
      max-width:820px;
      margin-bottom:32px;
      color:var(--muted);
      font-size:22px;
    }

    .hero-actions,.button-row{
      display:flex;
      flex-wrap:wrap;
      gap:12px;
      align-items:center;
    }

    .btn{
      min-height:52px;
      padding:12px 19px;
      border:1px solid transparent;
      border-radius:14px;
      cursor:pointer;
      text-decoration:none;
      font-size:16px;
      font-weight:850;
      transition:.16s ease;
    }

    .btn:hover{transform:translateY(-1px)}
    .btn:active{transform:translateY(1px)}
    .btn.primary{background:var(--accent);color:#fff}
    .btn.secondary{background:var(--surface);border-color:var(--line);color:var(--ink)}
    .btn.danger{background:var(--danger-bg);color:var(--danger);border-color:#e7c6c1}

    .hero-note{
      display:grid;
      grid-template-columns:repeat(3,1fr);
      gap:14px;
      margin-top:46px;
    }

    .mini-card{
      padding:22px;
      border:1px solid var(--line);
      border-radius:20px;
      background:rgba(255,253,248,.62);
    }

    .mini-card strong{
      display:block;
      margin-bottom:4px;
      font-size:20px;
    }

    .mini-card span{color:var(--muted);font-size:16px}

    section{
      padding:68px 0;
      border-top:1px solid rgba(212,206,193,.75);
    }

    .section-head{
      display:flex;
      justify-content:space-between;
      align-items:end;
      gap:28px;
      margin-bottom:30px;
    }

    .section-head p{
      max-width:590px;
      margin-bottom:0;
      color:var(--muted);
    }

    .section-index{
      color:var(--accent);
      font-weight:900;
      font-size:16px;
      letter-spacing:.08em;
    }

    .type-grid{
      display:grid;
      grid-template-columns:repeat(5,1fr);
      gap:14px;
    }

    .type-card{
      position:relative;
      min-height:330px;
      padding:24px;
      border:1px solid var(--line);
      border-radius:var(--radius);
      background:var(--surface);
      box-shadow:var(--shadow);
    }

    .type-card .number{
      display:inline-grid;
      place-items:center;
      width:42px;
      height:42px;
      margin-bottom:34px;
      border-radius:50%;
      color:var(--accent);
      background:var(--accent-2);
      font-weight:900;
    }

    .level{
      margin:0 0 12px;
      color:var(--accent);
      font-size:16px;
      font-weight:900;
    }

    .risk{
      margin-top:18px;
      padding-top:16px;
      border-top:1px solid var(--line);
      color:var(--muted);
      font-size:16px;
    }

    .panel{
      padding:30px;
      border:1px solid var(--line);
      border-radius:var(--radius);
      background:var(--surface);
      box-shadow:var(--shadow);
    }

    .form-grid{
      display:grid;
      grid-template-columns:repeat(2,1fr);
      gap:18px;
    }

    .field{
      display:flex;
      flex-direction:column;
      gap:8px;
    }

    label{font-weight:800}

    input,select,textarea{
      width:100%;
      min-height:54px;
      padding:12px 14px;
      border:1px solid #bdb7ac;
      border-radius:12px;
      color:var(--ink);
      background:#fff;
      font-size:17px;
    }

    textarea{min-height:120px;resize:vertical}

    .full{grid-column:1/-1}

    .status{
      display:none;
      margin-top:18px;
      padding:14px 16px;
      border-radius:12px;
      background:var(--ok-bg);
      color:var(--ok);
      font-weight:800;
      font-size:16px;
    }

    .status.show{display:block}

    .object{
      margin-top:26px;
      padding:20px;
      border-left:5px solid var(--accent);
      border-radius:0 16px 16px 0;
      background:var(--accent-2);
    }

    .object code{
      font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
      font-size:16px;
      white-space:normal;
    }

    .object strong{
      display:block;
      margin-bottom:8px;
    }

    .quote-layout{
      display:grid;
      grid-template-columns:1.25fr .75fr;
      gap:18px;
    }

    .table-wrap{
      overflow-x:auto;
      border:1px solid var(--line);
      border-radius:18px;
      background:var(--surface);
    }

    table{
      width:100%;
      min-width:720px;
      border-collapse:collapse;
    }

    th,td{
      padding:17px 18px;
      border-bottom:1px solid var(--line);
      text-align:left;
      vertical-align:top;
      font-size:16px;
    }

    th{
      background:var(--surface-2);
      font-weight:900;
    }

    tr:last-child td{border-bottom:0}

    .badge{
      display:inline-block;
      padding:5px 10px;
      border-radius:999px;
      font-size:16px;
      font-weight:900;
      white-space:nowrap;
    }

    .include{background:var(--ok-bg);color:var(--ok)}
    .exclude{background:var(--danger-bg);color:var(--danger)}
    .extra{background:var(--warm-bg);color:var(--warm)}

    .boundary-list{
      display:grid;
      gap:12px;
    }

    .boundary{
      padding:17px;
      border-radius:16px;
      background:var(--bg);
      border:1px solid var(--line);
    }

    .boundary strong{
      display:block;
      margin-bottom:4px;
    }

    .boundary span{font-size:16px;color:var(--muted)}

    .delivery-grid{
      display:grid;
      grid-template-columns:repeat(4,1fr);
      gap:14px;
    }

    .delivery-card{
      padding:22px;
      border:1px solid var(--line);
      border-radius:20px;
      background:var(--surface);
    }

    .delivery-card .icon{
      display:grid;
      place-items:center;
      width:44px;
      height:44px;
      margin-bottom:18px;
      border-radius:14px;
      background:var(--surface-2);
      font-weight:900;
    }

    .delivery-card p{
      margin-bottom:0;
      color:var(--muted);
      font-size:16px;
    }

    .check-list{
      display:grid;
      gap:10px;
    }

    .check-row{
      display:grid;
      grid-template-columns:auto 1fr auto;
      gap:14px;
      align-items:center;
      padding:17px;
      border:1px solid var(--line);
      border-radius:16px;
      background:var(--surface);
    }

    .check-row input{
      width:22px;
      height:22px;
      min-height:auto;
      accent-color:var(--accent);
    }

    .check-row strong{display:block}
    .check-row span{font-size:16px;color:var(--muted)}

    .result{
      min-width:86px;
      text-align:center;
      padding:6px 9px;
      border-radius:999px;
      background:var(--surface-2);
      font-size:16px;
      font-weight:900;
    }

    .rule-grid{
      display:grid;
      grid-template-columns:repeat(2,1fr);
      gap:16px;
    }

    .rule{
      padding:24px;
      border-radius:20px;
      border:1px solid var(--line);
      background:var(--surface);
    }

    .rule p{color:var(--muted);margin-bottom:0}

    .important{
      margin-top:24px;
      padding:24px;
      border-radius:20px;
      background:#242c29;
      color:#fff;
    }

    .important h3{color:#fff}
    .important p{margin-bottom:0;color:#e4ebe7}

    .summary{
      padding:42px;
      border-radius:30px;
      background:var(--accent);
      color:#fff;
    }

    .summary h2{color:#fff}
    .summary p{color:#e5eee9}
    .summary .btn.secondary{
      background:#fff;
      border-color:#fff;
    }

    .saved-box{
      margin-top:20px;
      padding:18px;
      border:1px dashed var(--line);
      border-radius:16px;
      background:rgba(255,255,255,.08);
      font-size:16px;
    }

    footer{
      padding:44px 0 60px;
      color:var(--muted);
      font-size:16px;
    }

    footer strong{color:var(--ink)}

    @media(max-width:920px){
      .type-grid{grid-template-columns:repeat(2,1fr)}
      .delivery-grid{grid-template-columns:repeat(2,1fr)}
      .quote-layout{grid-template-columns:1fr}
      .hero-note{grid-template-columns:1fr}
    }

    @media (max-width: 640px){
      body{font-size:18px;line-height:1.7}
      .wrap{width:min(100% - 28px,1180px)}

      .site-header{
        position:relative;
        flex-direction:column;
        align-items:flex-start;
        padding:18px 14px;
      }

      .nav{
        width:100%;
        flex-wrap:nowrap;
        overflow-x:auto;
        padding-bottom:4px;
      }

      .nav a{
        flex:0 0 auto;
        font-size:16px;
      }

      .hero{padding:58px 0 38px}
      h1{font-size:46px}
      h2{font-size:32px}
      h3{font-size:23px}
      .lead{font-size:20px}
      p,li{font-size:18px}

      section{padding:52px 0}

      .section-head{
        display:block;
        margin-bottom:24px;
      }

      .section-index{margin-bottom:8px}

      .type-grid,
      .rule-grid,
      .form-grid,
      .delivery-grid{
        grid-template-columns:1fr;
      }

      .full{grid-column:auto}

      .type-card{min-height:auto}
      .panel{padding:20px}
      .summary{padding:26px 22px}

      input,select,textarea{font-size:18px}

      .btn,
      .eyebrow,
      .level,
      .risk,
      .mini-card span,
      .boundary span,
      .delivery-card p,
      .check-row span,
      .result,
      .status,
      th,td,
      footer,
      .object code,
      .saved-box{
        font-size:16px;
      }

      .check-row{
        grid-template-columns:auto 1fr;
      }

      .result{
        grid-column:2;
        justify-self:start;
      }
    }

.site-header{position:relative!important}
