@media(max-width:640px){.site-header{flex-direction:column;align-items:flex-start}.site-nav{gap:12px}.type-grid,.rule-grid,.form-grid,.delivery-grid{grid-template-columns:1fr}.btn{display:block;width:100%;text-align:center}}
</style>
